namespace {unsigned checks{};std::atomic<bool>counting{};std::atomic<std::size_t>allocations{};}
void*operator new(std::size_t count){if(counting)++allocations;if(auto*p=std::malloc(count?count:1))return p;throw std::bad_alloc();}void*operator new[](std::size_t count){return ::operator new(count);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}
